// domain/services/transfer.js - stateless module, no class needed
export function transfer({ from, to, amount, rates, clock }) {
  if (amount <= 0) throw new DomainError("amount must be positive");
  const moved = rates.convert(amount, to.currency);
  from.withdraw(moved);
  to.deposit(moved);
  return { at: clock.now(), amount: moved };
}
